create or replace function public.preserve_duplicate_market_snapshot(p_canonical text,p_duplicate text) returns void language sql security invoker set search_path=public,pg_temp as $$ update public.football_feature_matches canonical set last_pre_match_market=duplicate.last_pre_match_market,last_pre_match_market_at=duplicate.last_pre_match_market_at from public.football_feature_matches duplicate where canonical.match_key=p_canonical and duplicate.match_key=p_duplicate and duplicate.last_pre_match_market_at is not null and jsonb_typeof(duplicate.last_pre_match_market)='object' and duplicate.last_pre_match_market<>'{}'::jsonb and (canonical.last_pre_match_market_at is null or duplicate.last_pre_match_market_at>canonical.last_pre_match_market_at); $$;
revoke all on function public.preserve_duplicate_market_snapshot(text,text) from public,anon,authenticated;
grant execute on function public.preserve_duplicate_market_snapshot(text,text) to service_role;
comment on function public.preserve_duplicate_market_snapshot(text,text) is 'Copies the freshest verified pre-match market snapshot to the canonical fixture before a duplicate fixture is merged and deleted.';;
